-- 1. A master key protects credentials stored in this database (only needs to be created once)
CREATE MASTER KEY ENCRYPTION BY PASSWORD = 'ChooseAStrongPassword123!';

-- 2. A credential that always uses the workspace's own identity
CREATE DATABASE SCOPED CREDENTIAL cred_managed_identity
WITH IDENTITY = 'Managed Identity';

-- 3. Attach that credential to both external data sources
DROP EXTERNAL DATA SOURCE silver_lake;
CREATE EXTERNAL DATA SOURCE silver_lake
WITH (LOCATION = 'abfss://silver@stolistdevweu.dfs.core.windows.net/', CREDENTIAL = cred_managed_identity);

DROP EXTERNAL DATA SOURCE gold_lake;
CREATE EXTERNAL DATA SOURCE gold_lake
WITH (LOCATION = 'abfss://gold@stolistdevweu.dfs.core.windows.net/', CREDENTIAL = cred_managed_identity);
